def evaluate(expr: str) -> int:
    """
Evaluate an arithmetic expression containing non-negative integers, +, -, *, /, and parentheses, with normal operator precedence. Spaces may appear anywhere. Division is integer division that truncates toward zero."""

    # Tokenize the expression to handle multi-digit numbers and operators
    tokens = []
    current_number = ""
    for char in expr:
        if char.isdigit():
            current_number += char
        elif char in "+-*/()":
            if current_number:
                tokens.append(current_number)
                current_number = ""
            tokens.append(char)
        elif char.isspace():
            continue
    if current_number:
        tokens.append(current_number)

    # --- Shunting-yard Algorithm or direct evaluation using stacks ---

    values = []
    ops = []

    def apply_op(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            # Integer division truncating toward zero
            return int(a / b)
        raise ValueError(f"Unknown operator: {op}")

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isdigit():
            values.append(int(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            # Evaluate until matching '('
            while ops[-1] != '(':
                op = ops.pop()
                val2 = values.pop()
                val1 = values.pop()
                values.append(apply_op(op, val2, val1))
            ops.pop() # discard '('
        elif token in "+-*/":
            # Standard operator handling (assuming we only see operators here)
            ops.append(token)
        i += 1

    # Apply remaining operations in the operator stack
    while ops:
        op = ops.pop()
        if op == '(':
            # Should not happen if input is valid, but for robustness
            continue

        if len(values) < 2:
            # This indicates an invalid expression structure for this problem scope
            # For this problem, we assume valid input structure leading to a result.
            break 

        val2 = values.pop()
        val1 = values.pop()
        values.append(apply_op(op, val2, val1))

    return values[0] if values else 0
