def lcs_length(a: str, b: str) -> int:
    m, n = len(a), len(b)
    # dp[j] will store the LCS length for a[:i] and b[:j]
    dp = [0] * (n + 1)
    for i in range(1, m + 1):
        prev = 0  # dp[i-1][j-1] from the previous row
        for j in range(1, n + 1):
            temp = dp[j]  # store current dp[j] (which is dp[i-1][j])
            if a[i - 1] == b[j - 1]:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp
    return dp[n]
