import ast
import operator

def evaluate(expr: str) -> int:
    # Replace division to ensure integer division behavior
    # Python's // operator is floor division, but for negative numbers 
    # (which might occur during intermediate steps), we need truncation toward zero.
    # However, the prompt specifies non-negative integers and standard precedence.
    # In Python 3, the '/' operator is float division. 
    # To handle the expression string, we can use ast.parse and a NodeVisitor.

    def truncate_div(a, b):
        # Standard integer division that truncates toward zero
        return int(a / b)

    class Evaluator(ast.NodeVisitor):
        def __init__(self):
            self.operators = {
                ast.Add: operator.add,
                ast.Sub: operator.sub,
                ast.Mult: operator.mul,
                ast.Div: truncate_div,
            }

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            op_type = type(node.op)
            return self.operators[op_type](left, right)

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            if isinstance(node.op, ast.UAdd):
                return operand
            return operand

        def visit_Constant(self, node):
            return node.value

        def visit_Num(self, node): # For older python versions
            return node.n

    # Pre-process the string to ensure '/' is treated as integer division
    # Since we are using ast.parse, we can't easily change the operator type 
    # via string replacement if we want to be robust, but we can map 
    # the Div node to our custom function.

    # We replace '/' with '//' in the string to force integer division 
    # in the AST, but we must be careful with the truncation rule.
    # Actually, the prompt says "Division is integer division that truncates toward zero".
    # In Python, // is floor division. For positive numbers, they are the same.
    # For negative numbers, int(a / b) is different from a // b.
    # Example: int(-3 / 2) = -1, while -3 // 2 = -2.

    # To be safe, we replace '/' with '//' and then use a custom visitor 
    # that overrides the Div behavior.

    expr = expr.replace('/', '//')
    tree = ast.parse(expr, mode='eval')

    # We need to override the Div behavior in the visitor
    class CustomEvaluator(Evaluator):
        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if isinstance(node.op, ast.FloorDiv):
                return int(left / right)
            return super().visit_BinOp(node)

    return CustomEvaluator().visit(tree)
